// Where the check sits among the eleven paths, so the drawing keeps the
// file's order (the check is the third shape, inside the first word).
export const WORDMARK_CHECK_INDEX = 2;

export const BrandMark: FC = () => (
  <svg class="brand-mark" viewBox="0 0 32 32" width="32" height="32" aria-hidden="true">
    <path fill="currentColor" fill-rule="evenodd" d={MARK_INK_PATH} />
    <path class="mark-check" fill={MARK_CHECK_COLOUR} fill-rule="evenodd" d={MARK_CHECK_PATH} />
  </svg>
);

// The whole lockup, as brand/lockup.svg draws it: the mark, then the name in
// letters drawn as paths, on a 201 by 32 box shown 24 px tall in the top bar.
// Everything is in currentColor but the check, which takes --check. The
// title names the image for anything that reads it on its own.
export const BrandLockup: FC<{ name: string }> = ({ name }) => (
  <svg class="brand-lockup" viewBox="0 0 201 32" width="151" height="24" role="img">
    <title>{name}</title>
    <path fill="currentColor" fill-rule="evenodd" d={MARK_INK_PATH} />
    <path class="mark-check" fill={MARK_CHECK_COLOUR} fill-rule="evenodd" d={MARK_CHECK_PATH} />
    <path fill="currentColor" fill-rule="evenodd" d={LOCKUP_WORD_PATH} />
  </svg>
);

// The top bar's wordmark (brand/wordmark.svg) at 24 px tall, 170 wide, the
// shapes in the file's order. Everything is in currentColor but the check,
// which takes --check. The title names the image for anything that reads it
// on its own.
export const BrandWordmark: FC<{ name: string }> = ({ name }) => (
  <svg class="brand-wordmark" viewBox={WORDMARK_VIEWBOX} width="170" height="24" role="img">
    <title>{name}</title>
    {WORDMARK_INK_PATHS.slice(0, WORDMARK_CHECK_INDEX).map((d) => <path fill="currentColor" fill-rule="evenodd" d={d} />)}
    <path class="mark-check" fill={MARK_CHECK_COLOUR} fill-rule="evenodd" d={WORDMARK_CHECK_PATH} />
    {WORDMARK_INK_PATHS.slice(WORDMARK_CHECK_INDEX).map((d) => <path fill="currentColor" fill-rule="evenodd" d={d} />)}
  </svg>
);

// The data's own date when it has one, else today in UTC: the day a page
// reads years and late dates against. Closing states read the clock
// instead (src/closing.ts).
export function todayOf(dataAsOf: string | null | undefined): string {
  return dataAsOf && /^\d{4}-\d{2}-\d{2}/.test(dataAsOf) ? dataAsOf.slice(0, 10) : new Date().toISOString().slice(0, 10);
}

export function addDays(day: string, n: number): string {
  const d = new Date(`${day}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

// notice: the reference of a notice closing soon, so public/countdown.js can
// turn every chip of that notice on the page once its closing time passes.
// hidden: a closing-soon chip a list shows as the time left instead; the
// script turns it on with "Closing date passed" once the time comes.
export const StatusBadge: FC<{ status: string; lang: Lang; notice?: string; hidden?: boolean }> = ({ status, lang, notice, hidden }) => (
  <span class={`badge badge-${/^[a-z]+$/.test(status) ? status : "unknown"}`} data-notice={notice} hidden={hidden}>{statusLabel(lang, status)}</span>
);

// "Non-competitive" is the source's own term: the definition rides along as
// the tag's tooltip and is spelled out on the Methodology page it links to.
export const CompetitiveFlag: FC<{ value: Competitive; lang: Lang }> = ({ value, lang }) => {
  const v = competitiveOf(value);
  const kind = v === true ? "yes" : v === false ? "no" : "unstated";
  const tip: Key = v === true ? "competitive.def_yes" : v === false ? "competitive.def_no" : "competitive.def_unstated";
  return (
    <span class={`flag flag-${kind}`} title={t(lang, tip)}>
      {competitiveLabel(lang, value)}
    </span>
  );
};

export const Breadcrumb: FC<{ lang: Lang; crumbs: { name: string; path?: string }[] }> = ({ lang, crumbs }) => (
  <nav aria-label={t(lang, "common.breadcrumb")} class="breadcrumb">
    {crumbs.map((c, i) => (
      <>
        {i > 0 ? " / " : ""}
        {c.path ? <a href={c.path}>{c.name}</a> : c.name}
      </>
    ))}
  </nav>
);

// The page's own band: the trail back, the title, a one-line description and
// the page's actions (CSV, feed, watch) on the right. Anything else the head
// needs (a second line of facts) comes in as children under the description.
export const PageHead: FC<PropsWithChildren<{
  lang: Lang; title: unknown; lead?: unknown; crumbs?: { name: string; path?: string }[]; eyebrow?: unknown; actions?: unknown;
}>> = (p) => (
  <header class="page-head">
    {p.crumbs ? <Breadcrumb lang={p.lang} crumbs={p.crumbs} /> : null}
    <div class="page-head-row">
      <div class="page-head-text">
        {p.eyebrow ? <p class="eyebrow">{p.eyebrow as any}</p> : null}
        <h1>{p.title as any}</h1>
        {p.lead ? <p class="lead">{p.lead as any}</p> : null}
        {p.children}
      </div>
      {p.actions ? <div class="page-actions">{p.actions as any}</div> : null}
    </div>
  </header>
);

// A bordered region of the page under a labelled head band: the label on the
// left, a count or a small action on the right. Tables sit flush inside; any
// other block gets the panel's padding from the stylesheet. foot is the band
// along the bottom (pager, source line, keyboard hint).
export const Panel: FC<PropsWithChildren<{
  title: unknown; id?: string; count?: unknown; tools?: unknown; foot?: unknown; class?: string; label?: string;
}>> = (p) => (
  <section class={p.class ? `panel ${p.class}` : "panel"} aria-label={p.label}>
    <div class="panel-head">
      <h2 id={p.id}>{p.title as any}</h2>
      {p.count !== undefined || p.tools ? (
        <div class="panel-tools">
          {p.count !== undefined ? <span class="panel-count">{p.count as any}</span> : null}
          {p.tools as any}
        </div>
      ) : null}
    </div>
    {p.children}
    {p.foot ? <div class="panel-foot">{p.foot as any}</div> : null}
  </section>
);

// Search and social metadata. A page without an Seo object (errors, the
// thank-you page) gets only the site description: no canonical, no cards.
const MetaTags: FC<{ seo?: Seo; lang: Lang; title: string }> = ({ seo, lang, title }) => {
  if (!seo) return <meta name="description" content={defaultDescription(lang)} />;
  if (seo.noindex) {
    return (
      <>
        <meta name="description" content={seo.description} />
        <meta name="robots" content="noindex" />
      </>
    );
  }
  const url = canonicalUrl(seo.path, lang);
  const socialTitle = seo.socialTitle ?? title;
  return (
    <>
      <meta name="description" content={seo.description} />
      <link rel="canonical" href={url} />
      {alternates(seo.path).map((a) => (
        <link rel="alternate" hreflang={a.hreflang} href={a.href} />
      ))}
      <meta property="og:site_name" content={t(lang, "site.name")} />
      <meta property="og:type" content="website" />
      <meta property="og:url" content={url} />
      <meta property="og:title" content={socialTitle} />
      <meta property="og:description" content={seo.description} />
      <meta property="og:locale" content={lang === "fr" ? "fr_CA" : "en_CA"} />
      <meta property="og:locale:alternate" content={lang === "fr" ? "en_CA" : "fr_CA"} />
      <meta property="og:image" content={absoluteUrl("/apple-touch-icon.png")} />
      <meta name="twitter:card" content="summary" />
      <meta name="twitter:title" content={socialTitle} />
      <meta name="twitter:description" content={seo.description} />
      {(seo.jsonLd ?? []).map((data) => (
        <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: scriptJson(data) }}></script>
      ))}
    </>
  );
};

// What the shell takes from the request, through a render context set by
// page() so the pages, which already hand Layout their data date, do not
// each pass it: the rail's counts, and the page's own address as viewKey()
// writes it, so the rail can mark the item that leads exactly here. Outside
// page() (the error handler) the rail shows its links bare.
export type Shell = { rail: RailCounts | null; here: string };
export const RailContext = createContext<Shell | null>(null);

// A path and its query as one view: the language and the page number left
// out (they show the same view), the other parameters in a fixed order.
export function viewKey(pathAndQuery: string): string {
  const url = new URL(pathAndQuery, "https://view.invalid");
  const params = [...url.searchParams].filter(([k]) => k !== "lang" && k !== "page").sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  const query = new URLSearchParams(params).toString();
  return `${url.pathname}${query ? `?${query}` : ""}`;
}

// An entry of the rail: children are views of the entry's own list.
// `section` is the Layout `active` value of the pages under it. `short` is a
// child's label under its parent in the tree ("In 2026"); below 1000 px the
// tree flattens into a wrap of items, where the full label stands alone.
type RailEntry = {
  href: string; label: string; short?: string; n?: number; section?: string; soon?: boolean; children?: RailEntry[];
};
type RailState = "current" | "ancestor" | null;

const RailLink: FC<{ lang: Lang; e: RailEntry; state: RailState; child?: boolean }> = ({ lang, e, state, child }) => (
  <a class={["rail-item", child ? "rail-child" : "", e.soon ? "soon" : "", state === "ancestor" ? "rail-ancestor" : ""].filter(Boolean).join(" ")}
    href={e.href} aria-current={state === "current" ? "page" : undefined}>
    <span class="rail-label">
      {e.short ? <><span class="rail-short">{e.short}</span><span class="rail-full">{e.label}</span></> : e.label}
    </span>
    {/* The closing-soon count goes down as public/countdown.js sees a notice on the page close. */}
    {e.n !== undefined ? <span class="rail-n" data-soon-count={e.soon ? "" : undefined}>{fmtInt(e.n, lang)}</span> : null}
  </a>
);

const RailItem: FC<{ lang: Lang; e: RailEntry; current: boolean }> = ({ lang, e, current }) => (
  <li>
    <RailLink lang={lang} e={e} state={current ? "current" : null} />
  </li>
);

// The overview as a tree: one item is current, the one whose address is the
// page's (viewKey); its parent, when it has one, reads as an ancestor. A page
// no item leads to exactly (a notice, a profile, a filtered list) marks its
// section's item as the ancestor, so the reader still sees where they are.
export function railStates(entries: readonly RailEntry[], here: string, section?: string): Map<RailEntry, RailState> {
  const states = new Map<RailEntry, RailState>();
  const all = entries.flatMap((e) => [e, ...(e.children ?? [])]);
  const current = here ? all.find((e) => viewKey(e.href) === here) : undefined;
  for (const e of entries) {
    if (e === current) states.set(e, "current");
    else if (current && e.children?.includes(current)) states.set(e, "ancestor");
    else if (!current && section !== undefined && e.section === section) states.set(e, "ancestor");
    for (const k of e.children ?? []) states.set(k, k === current ? "current" : null);
  }
  return states;
}

// The left rail: a live index of counts, the browse links, and the reader's
// own lists. The last group is anchored to the rail's foot, so the items an
// account adds later (saved searches, alerts, the account itself) go there
// without moving anything above them. Nothing in it assumes a signed-in
// reader: the watchlist lives in this browser, and alerts are a link to the
// page that says they are coming and takes an address meanwhile.
const Rail: FC<{ lang: Lang; active?: string; rail: RailCounts | null; here: string }> = ({ lang, active, rail, here }) => {
  const year = rail?.year ?? new Date().toISOString().slice(0, 4);
  const expiring = rail?.ending12m !== undefined || rail?.ending3m !== undefined;
  const index: RailEntry[] = [
    {
      href: "/tenders", label: t(lang, "rail.open"), n: rail?.open, section: "/tenders",
      children: [
        { href: "/tenders/new", label: t(lang, "rail.new"), n: rail?.newToday },
        { href: "/tenders?closing=7", label: t(lang, "rail.closing", { n: CLOSING_SOON_DAYS }), n: rail?.closingSoon, soon: true },
      ],
    },
    {
      href: "/awards", label: t(lang, "rail.awards"), n: rail?.awards, section: "/awards",
      children: [{
        href: `/awards/${year}`, short: t(lang, "rail.awards_year", { year }), label: t(lang, "rail.awards_year_full", { year }), n: rail?.awardsYear,
      }],
    },
    ...(expiring ? [{
      href: "/expiring", label: t(lang, "rail.expiring"), n: rail?.ending12m, section: "/expiring",
      children: [{ href: "/expiring/3m", short: t(lang, "expiring.window_3m"), label: t(lang, "rail.ending_3m_full"), n: rail?.ending3m }],
    }] : []),
    { href: "/organizations", label: t(lang, "nav.organizations"), n: rail?.organizations, section: "/organizations" },
    { href: "/buyers", label: t(lang, "nav.buyers"), n: rail?.buyers, section: "/buyers" },
  ];
  const states = railStates(index, here, active);
  const browse: RailEntry[] = [
    { href: "/segments", label: t(lang, "nav.segments"), section: "/segments" },
    { href: "/rankings", label: t(lang, "nav.rankings"), section: "/rankings" },
    { href: "/feeds", label: t(lang, "nav.feeds"), section: "/feeds" },
    { href: "/data", label: t(lang, "nav.data"), section: "/data" },
    { href: "/methodology", label: t(lang, "nav.methodology"), section: "/methodology" },
  ];
  return (
    <nav class="rail" aria-label={t(lang, "nav.main_label")}>
      <div class="rail-group">
        <p class="rail-head" id="rail-index">{t(lang, "rail.index")}</p>
        <ul aria-labelledby="rail-index" class="rail-tree">
          {index.map((e) => (
            <li class={e.children ? "rail-parent" : undefined}>
              <RailLink lang={lang} e={e} state={states.get(e) ?? null} />
              {e.children ? (
                <ul class="rail-sub">
                  {e.children.map((k) => <li><RailLink lang={lang} e={k} state={states.get(k) ?? null} child /></li>)}
                </ul>
              ) : null}
            </li>
          ))}
        </ul>
      </div>
      <div class="rail-group rail-browse">
        <p class="rail-head" id="rail-browse">{t(lang, "rail.browse")}</p>
        <ul aria-labelledby="rail-browse">
          {browse.map((e) => <RailItem lang={lang} e={e} current={e.section === active} />)}
        </ul>
      </div>
      <div class="rail-group rail-user">
        <p class="rail-head" id="rail-lists">{t(lang, "rail.lists")}</p>
        <ul aria-labelledby="rail-lists">
          <li>
            <a class="rail-item" href="/watchlist" aria-current={active === "/watchlist" ? "page" : undefined}>
              <span class="rail-label">{t(lang, "footer.watchlist")}</span>
              <span class="rail-n" data-watch-count="" hidden></span>
            </a>
          </li>
          <li>
            <a class="rail-item rail-later" href="/alerts" aria-current={active === "/alerts" ? "page" : undefined}>
              <span class="rail-label">{t(lang, "rail.alerts_soon")}</span>
            </a>
          </li>
        </ul>
      </div>
    </nav>
  );
};

// The stylesheet's version: bump it with any change to public/styles.css so a
// cached copy is never paired with new markup.
export const STYLES_VERSION = 8;

// The top bar's search field, on every page: a plain GET form to /search
// (src/pages/search.tsx), so it works without the scripts. A form with one
// field submits on Enter, so it needs no button. query fills it on the
// results page.
export const TopbarSearch: FC<{ lang: Lang; query?: string }> = ({ lang, query }) => (
  <form class="topbar-search" method="get" action="/search" role="search">
    <input type="search" name="q" value={query ?? ""} maxlength={200} autocomplete="off"
      placeholder={t(lang, "search.placeholder")} aria-label={t(lang, "search.label")} />
  </form>
);

export const Layout: FC<
  PropsWithChildren<{ lang: Lang; title: string; dataAsOf: string | null; active?: string; head?: unknown; seo?: Seo; query?: string }>
> = (props) => {
  const { lang, active } = props;
  const title = props.seo?.title ?? pageTitle(props.title);
  const shell = useContext(RailContext);
  return (
    <html lang={lang}>
      <head>
        <meta charset="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <title>{title}</title>
        <link rel="stylesheet" href={`/styles.css?v=${STYLES_VERSION}`} />
        <script src="/theme.js"></script>
        <script src="/links.js" defer></script>
        <script src="/watchlist.js" defer></script>
        <link rel="preload" href="/fonts/InterVariable.woff2" as="font" type="font/woff2" crossorigin="anonymous" />
        <link rel="icon" href="/favicon.ico" sizes="48x48" />
        <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
        <link rel="apple-touch-icon" href="/apple-touch-icon.png" />
        <MetaTags seo={props.seo} lang={lang} title={props.title} />
        {props.head as any}
      </head>
      <body>
        <a class="skip" href="#main">{t(lang, "nav.skip")}</a>
        <header class="topbar">
          <a href="/" class="brand" aria-label={t(lang, "site.name")}>
            <BrandWordmark name={t(lang, "site.name")} />
          </a>
          <TopbarSearch lang={lang} query={props.query} />
          <div class="topbar-meta">
            <span class="asof">{t(lang, "nav.data_date", { date: props.dataAsOf ?? t(lang, "common.na") })}</span>
            <a href={`?lang=${lang === "fr" ? "en" : "fr"}`} class="lang-toggle" rel="nofollow">
              {t(lang, "nav.lang")}
            </a>
            <button type="button" class="theme-toggle">
              <span class="when-light">{t(lang, "nav.dark")}</span>
              <span class="when-dark">{t(lang, "nav.light")}</span>
            </button>
          </div>
        </header>
        <div class="frame">
          <Rail lang={lang} active={active} rail={shell?.rail ?? null} here={shell?.here ?? ""} />
          <div class="content">
            <main id="main">{props.children}</main>
            <footer class="site-footer">
              <div class="footer-row">
                <span class="footer-sources">
                  {t(lang, shell?.rail?.lobbyingLoaded ? "footer.sources" : "footer.sources_no_lobbying")}{" "}
                  <a href="/data#sources">{t(lang, "footer.sources_link")}</a>
                </span>
                <span class="footer-links">
                  <a href="/segments">{t(lang, "nav.segments")}</a>
                  <a href="/rankings">{t(lang, "nav.rankings")}</a>
                  <a href="/methodology">{t(lang, "footer.methodology")}</a>
                  <a href="/data#downloads">{t(lang, "footer.download")}</a>
                  <a href="/feeds">{t(lang, "footer.feeds")}</a>
                  <a href="/alerts">{t(lang, "footer.alerts")}</a>
                  <a href="/watchlist">{t(lang, "footer.watchlist")}</a>
                  <a href="/corrections">{t(lang, "footer.corrections")}</a>
                  <a href="/cite">{t(lang, "footer.cite")}</a>
                  <a href="/about">{t(lang, "footer.about")}</a>
                  <a href="/terms">{t(lang, "footer.terms")}</a>
                  <a href="/privacy">{t(lang, "footer.privacy")}</a>
                </span>
              </div>
            </footer>
          </div>
        </div>
      </body>
    </html>
  );
};

// Every page goes out through here: the rail's counts are loaded once and
// handed to the shell, with the page's own address, through RailContext
// while the page renders. A failure to read them leaves the rail's links
// without counts, never the page down.
export async function page(c: Context<AppEnv>, body: unknown, status = 200): Promise<Response> {
  let rail: RailCounts | null = null;
  try {
    rail = await loadRail(c.env);
  } catch {
    rail = null;
  }
  const url = new URL(c.req.url);
  const shell: Shell = { rail, here: viewKey(`${url.pathname}${url.search}`) };
  c.header("Cache-Control", status === 200 ? "public, max-age=300" : "no-store");
  return c.html(html`<!doctype html>${(<RailContext.Provider value={shell}>{body as any}</RailContext.Provider>) as any}`, status as any);
}

// Shown while the data files have not been published yet (before the first
// nightly run, or on a dev checkout without `npm run data:local`).
export function noDataPage(c: Context<AppEnv>, title: Key): Promise<Response> {
  const lang = c.get("lang") ?? "en";
  return page(
    c,
    <Layout lang={lang} title={t(lang, title)} dataAsOf={null}>
      <PageHead lang={lang} title={t(lang, "error.no_data")} lead={t(lang, "error.no_data_text")} />
    </Layout>,
    503,
  );
}

// A 404 for a well-formed id or reference that no file holds, with a way back.
export function notFoundPage(
  c: Context<AppEnv>, dataAsOf: string | null, title: Key, back: string, backKey: Key,
): Promise<Response> {
  const lang = c.get("lang") ?? "en";
  return page(
    c,
    <Layout lang={lang} title={t(lang, title)} dataAsOf={dataAsOf}>
      <PageHead lang={lang} title={t(lang, title)} lead={<a href={back}>{t(lang, backKey)}</a>} />
    </Layout>,
    404,
  );
}

// The canonical form of a path is lower case; anything else is sent there,
// with the language query kept.
export function lowerRedirect(c: Context<AppEnv>, path: string): Response | null {
  const url = new URL(c.req.url);
  if (url.pathname === path) return null;
  c.header("Cache-Control", "public, max-age=300");
  return c.redirect(`${path}${url.search}`, 301);
}
